// MinimockGetSqrDone returns true if the count of the GetSqr invocations corresponds
// the number of defined expectations
func (m *ExecutorMock) MinimockGetSqrDone() bool {
	if m.GetSqrMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.GetSqrMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.GetSqrMock.invocationsDone()
}

// MinimockGetSqrInspect logs each unmet expectation
func (m *ExecutorMock) MinimockGetSqrInspect() {
	for _, e := range m.GetSqrMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to ExecutorMock.GetSqr at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterGetSqrCounter := mm_atomic.LoadUint64(&m.afterGetSqrCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.GetSqrMock.defaultExpectation != nil && afterGetSqrCounter < 1 {
		if m.GetSqrMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to ExecutorMock.GetSqr at\n%s", m.GetSqrMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to ExecutorMock.GetSqr at\n%s with params: %#v", m.GetSqrMock.defaultExpectation.expectationOrigins.origin, *m.GetSqrMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcGetSqr != nil && afterGetSqrCounter < 1 {
		m.t.Errorf("Expected call to ExecutorMock.GetSqr at\n%s", m.funcGetSqrOrigin)
	}

	if !m.GetSqrMock.invocationsDone() && afterGetSqrCounter > 0 {
		m.t.Errorf("Expected %d calls to ExecutorMock.GetSqr at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.GetSqrMock.expectedInvocations), m.GetSqrMock.expectedInvocationsOrigin, afterGetSqrCounter)
	}
}

