// SelectSqr implements mm_db.Executor
func (mmSelectSqr *ExecutorMock) SelectSqr(ctx context.Context, dest any, q mm_db.Sqlizer) (err error) {
	mm_atomic.AddUint64(&mmSelectSqr.beforeSelectSqrCounter, 1)
	defer mm_atomic.AddUint64(&mmSelectSqr.afterSelectSqrCounter, 1)

	mmSelectSqr.t.Helper()

	if mmSelectSqr.inspectFuncSelectSqr != nil {
		mmSelectSqr.inspectFuncSelectSqr(ctx, dest, q)
	}

	mm_params := ExecutorMockSelectSqrParams{ctx, dest, q}

	// Record call args
	mmSelectSqr.SelectSqrMock.mutex.Lock()
	mmSelectSqr.SelectSqrMock.callArgs = append(mmSelectSqr.SelectSqrMock.callArgs, &mm_params)
	mmSelectSqr.SelectSqrMock.mutex.Unlock()

	for _, e := range mmSelectSqr.SelectSqrMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.err
		}
	}

	if mmSelectSqr.SelectSqrMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmSelectSqr.SelectSqrMock.defaultExpectation.Counter, 1)
		mm_want := mmSelectSqr.SelectSqrMock.defaultExpectation.params
		mm_want_ptrs := mmSelectSqr.SelectSqrMock.defaultExpectation.paramPtrs

		mm_got := ExecutorMockSelectSqrParams{ctx, dest, q}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmSelectSqr.t.Errorf("ExecutorMock.SelectSqr got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSelectSqr.SelectSqrMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.dest != nil && !minimock.Equal(*mm_want_ptrs.dest, mm_got.dest) {
				mmSelectSqr.t.Errorf("ExecutorMock.SelectSqr got unexpected parameter dest, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSelectSqr.SelectSqrMock.defaultExpectation.expectationOrigins.originDest, *mm_want_ptrs.dest, mm_got.dest, minimock.Diff(*mm_want_ptrs.dest, mm_got.dest))
			}

			if mm_want_ptrs.q != nil && !minimock.Equal(*mm_want_ptrs.q, mm_got.q) {
				mmSelectSqr.t.Errorf("ExecutorMock.SelectSqr got unexpected parameter q, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSelectSqr.SelectSqrMock.defaultExpectation.expectationOrigins.originQ, *mm_want_ptrs.q, mm_got.q, minimock.Diff(*mm_want_ptrs.q, mm_got.q))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmSelectSqr.t.Errorf("ExecutorMock.SelectSqr got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmSelectSqr.SelectSqrMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmSelectSqr.SelectSqrMock.defaultExpectation.results
		if mm_results == nil {
			mmSelectSqr.t.Fatal("No results are set for the ExecutorMock.SelectSqr")
		}
		return (*mm_results).err
	}
	if mmSelectSqr.funcSelectSqr != nil {
		return mmSelectSqr.funcSelectSqr(ctx, dest, q)
	}
	mmSelectSqr.t.Fatalf("Unexpected call to ExecutorMock.SelectSqr. %v %v %v", ctx, dest, q)
	return
}

