// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *ExecutorMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockExecInspect()

			m.MinimockExecSqrInspect()

			m.MinimockGetInspect()

			m.MinimockGetSqrInspect()

			m.MinimockSelectInspect()

			m.MinimockSelectSqrInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *ExecutorMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *ExecutorMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockExecDone() &&
		m.MinimockExecSqrDone() &&
		m.MinimockGetDone() &&
		m.MinimockGetSqrDone() &&
		m.MinimockSelectDone() &&
		m.MinimockSelectSqrDone()
}
